    (12295, 12340, ".download-row{grid-template-columns:48px 1fr}"),
    (12340, 12392, ".download-row>.btn{grid-column:2;justify-self:start}"),
    (14024, 14063, ".download-row:first-child{margin-top:0}"),
    (53742, 53803, ".download-progress .player-watched{transition:none!important}"),
    (75028, 75095, ".download-group-art{width:58px;height:77px;display:block;flex:none}"),
    (75096, 75146, ".download-group-content{min-width:0;display:block}"),
    (75147, 75254, ".download-group-title{display:block;font-size:14px;font-weight:720;line-height:1.34;overflow-wrap:anywhere}"),
    (75255, 75358, ".download-group-summary{display:block;margin-top:5px;font-size:11px;line-height:1.6;color:var(--muted)}"),
    (75576, 75648, ".download-group .download-progress-line{max-width:520px;margin-top:10px}"),
    (75649, 75699, ".download-group .download-progress{max-width:none}"),
    (75700, 75830, ".download-group-dismiss-wrap{display:flex;align-items:center;justify-content:center;align-self:center;flex:none;margin:0 12px 0 0}"),
    (76419, 76454, ".download-episode-main{min-width:0}"),
    (76455, 76527, ".download-episode-name{font-size:12.5px;font-weight:680;line-height:1.4}"),
    (76528, 76640, ".download-episode-meta{display:flex;gap:6px;align-items:center;margin-top:4px;font-size:11px;color:var(--muted)}"),
    (76641, 76708, ".download-episode-status[data-status=\"Completed\"]{color:var(--ink)}"),
    (76709, 76776, ".download-episode-status[data-status=\"Failed\"]{color:var(--accent)}"),
    (76777, 76850, ".download-episode .download-progress-line{margin-top:9px;max-width:470px}"),
    (76851, 76941, ".download-episode-actions{display:flex;align-items:center;justify-content:end;min-width:0}"),
    (76942, 76976, ".download-episode-actions{gap:6px}"),
    (78357, 78400, ".download-group-art{width:48px;height:66px}"),
    (78400, 78447, ".download-group-dismiss-wrap{margin-right:10px}"),
    (78447, 78484, ".download-group-title{font-size:13px}"),
    (78484, 78525, ".download-group-summary{font-size:10.5px}"),
    (78643, 78689, ".download-group-dismiss-wrap{margin:0 8px 0 0}"),
    (79676, 79739, ".download-action-btn.download-action-retry{color:var(--accent)}"),
    (79808, 79899, ".download-episode-actions{display:flex;align-items:center;justify-content:flex-end;gap:6px}"),
