    (196249, 196375, "body[data-theme] .download-groups .download-group-title{font-size:14px;font-weight:720;color:var(--fg);letter-spacing:-.015em}"),
    (196376, 196487, "body[data-theme] .download-groups .download-group-summary{font-size:11px;color:var(--card-meta);margin-top:5px}"),
    (196488, 196578, "body[data-theme] .download-groups .download-group .download-progress-line{margin-top:11px}"),
    (196802, 196906, "body[data-theme] .download-groups .download-episode-status[data-status=\"Completed\"]{color:var(--accent)}"),
    (196907, 196993, "body[data-theme] .download-groups .download-percent{font-variant-numeric:tabular-nums}"),
